// ── Shirt tone ──
// The reference title sits on a dark shirt. This color-keyed filter tints only
// light, low-saturation pixels of the cut-out (the shirt) navy; skin, hair,
// beard and watch fail the key and keep their own colors.
export function ShirtTone({ id }) {
  return <svg className="sienna-filter-defs" width="0" height="0" aria-hidden="true" focusable="false">
    <filter id={id} colorInterpolationFilters="sRGB">
      <feColorMatrix in="SourceGraphic" type="matrix" values="0 0 0 0 .13 0 0 0 0 .27 0 0 0 0 .56 -24 5 24 0 -1.2" result="key" />
      <feComposite in="key" in2="SourceAlpha" operator="in" result="tone" />
      <feBlend in="tone" in2="SourceGraphic" mode="multiply" />
    </filter>
  </svg>;
}

// ── About banner ──
// Original brush field (generated, not traced from the reference): a rounded
// block, narrower at the top, with a diagonal cut over the top-right corner,
