export function AboutPortrait({ src, alt, cutout }) {
  const id = "sienna-about-art";
  return <svg className="sienna-about-art" viewBox="0 0 450 450" role="img" aria-label={alt}>
    <defs>
      <linearGradient id={`${id}-paint`} x1="0" y1="0" x2="1" y2="0">
        <stop offset="0" stopColor="hsl(24,82%,60%)" />
        <stop offset=".55" stopColor="hsl(19,90%,54%)" />
        <stop offset="1" stopColor="hsl(13,95%,47%)" />
      </linearGradient>
      <filter id={`${id}-dry`} x="-5%" y="-5%" width="110%" height="110%" colorInterpolationFilters="sRGB">
        <feTurbulence type="fractalNoise" baseFrequency=".2 .05" numOctaves="2" seed="3" result="warp" />
        <feDisplacementMap in="SourceGraphic" in2="warp" scale="6" xChannelSelector="R" yChannelSelector="G" />
      </filter>
      <mask id={`${id}-mask`} maskUnits="userSpaceOnUse" x="-50" y="-80" width="550" height="600">
        {cutout && <rect x="-50" y="-80" width="550" height="280" fill="#fff" />}
        <g filter={`url(#${id}-dry)`}><AboutPaint field="#fff" marks="#000" /></g>
      </mask>
    </defs>
    <g filter={`url(#${id}-dry)`}><AboutPaint field={`url(#${id}-paint)`} /></g>
    <image href={src} mask={`url(#${id}-mask)`} {...(cutout ? { x: -25, y: -17, width: 496, height: 496 } : { x: 16, y: 148, width: 424, height: 304 })} preserveAspectRatio="xMidYMid slice" />
  </svg>;
}
